package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public final class FilmSearchActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout list;private EditText query;private TextView status;private Spinner choice;private List<TvBoxConfig.Site> sources=new ArrayList<>();private volatile int generation;private Future<?> searchJob;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=TvUi.root(this);root.addView(TvUi.text(this,"网络影视搜索",28,TvUi.INK));query=new EditText(this);query.setSingleLine(true);query.setTextColor(TvUi.INK);query.setHintTextColor(TvUi.MUTED);query.setHint("输入片名");root.addView(query);if(state!=null)query.setText(state.getString("query",""));try{sources=new SourceRepository(this).load().sites;}catch(Exception ignored){}List<String> names=new ArrayList<>();names.add("全部支持的标准 API");for(TvBoxConfig.Site site:sources)names.add(site.name);choice=new Spinner(this);choice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){if(v instanceof TextView)((TextView)v).setTextColor(TvUi.INK);}});root.addView(choice);LinearLayout buttons=TvUi.row(this);Button search=TvUi.button(this,"搜索"),back=TvUi.button(this,"返回");buttons.addView(search,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(back);root.addView(buttons);search.setOnClickListener(v->search());back.setOnClickListener(v->finish());status=TvUi.text(this,sources.isEmpty()?"请先在设置中导入 TVBox 配置。":"已加载 "+sources.size()+" 个标准 API，结果由所选源返回。",16,TvUi.MUTED);root.addView(status);ScrollView scroll=new ScrollView(this);list=TvUi.col(this);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private static final class Result{TvBoxConfig.Site site;List<VodApi.Movie> movies;Result(TvBoxConfig.Site s,List<VodApi.Movie> m){site=s;movies=m;}}
 private void search(){String word=query.getText().toString().trim();if(word.isEmpty()||sources.isEmpty()){TvUi.toast(this,sources.isEmpty()?"尚无支持的影视 API":"请输入片名");return;}int token=++generation;if(searchJob!=null)searchJob.cancel(true);int selected=choice.getSelectedItemPosition();List<TvBoxConfig.Site> targets=selected<=0?new ArrayList<>(sources):Collections.singletonList(sources.get(selected-1));status.setText("正在搜索…（最多等待 18 秒）");list.removeAllViews();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);searchJob=worker.submit(()->{if(token!=generation)return;ExecutorService requests=Executors.newFixedThreadPool(3);List<Callable<Result>> tasks=new ArrayList<>();for(TvBoxConfig.Site site:targets)tasks.add(()->new Result(site,VodApi.parse(PublicHttp.get(VodApi.query(site.api,"wd",word)))));List<Result> results=new ArrayList<>();int failed=0;try{for(Future<Result> future:requests.invokeAll(tasks,18,TimeUnit.SECONDS))try{if(future.isCancelled()){failed++;continue;}results.add(future.get());}catch(Exception e){failed++;}}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{requests.shutdownNow();}int failures=failed;runOnUiThread(()->{if(isDestroyed()||token!=generation)return;int total=0;for(Result result:results)for(VodApi.Movie movie:result.movies){if(total++>=120)break;Button card=TvUi.button(this,movie.title+"\n"+movie.category+" · "+movie.year+" · "+result.site.name);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.bottomMargin=TvUi.dp(this,8);list.addView(card,params);card.setOnClickListener(v->startActivity(new Intent(this,EpisodeActivity.class).putExtra("api",result.site.api).putExtra("source",result.site.name).putExtra("site",result.site.key).putExtra("movie",movie.id).putExtra("title",movie.title)));}status.setText("显示 "+Math.min(total,120)+" 项；失败/超时 "+failures+" 个源。影片列表不代表可播放。");});});}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("query",query.getText().toString());}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
